interface Notifier {
    void send(String message);
}

final class EmailNotifier implements Notifier {
    public void send(String message) {
        // base behavior: send email
        System.out.println("EMAIL: " + message);
    }
}

abstract class NotifierDecorator implements Notifier {
    protected final Notifier wrapped;

    protected NotifierDecorator(Notifier wrapped) {
        if (wrapped == null) throw new IllegalArgumentException("wrapped is required");
        this.wrapped = wrapped;
    }

    @Override
    public void send(String message) {
        wrapped.send(message); // default: pure forwarding
    }
}

final class SmsDecorator extends NotifierDecorator {
    SmsDecorator(Notifier wrapped) { super(wrapped); }

    @Override
    public void send(String message) {
        wrapped.send(message);          // inner channels first
        System.out.println("SMS: " + message); // then this layer
    }
}

final class EncryptDecorator extends NotifierDecorator {
    EncryptDecorator(Notifier wrapped) { super(wrapped); }

    @Override
    public void send(String message) {
        String cipher = "enc(" + message + ")"; // pre-process
        wrapped.send(cipher);                      // forward transformed input
    }
}

from abc import ABC, abstractmethod

class Pizza(ABC):
    @abstractmethod
    def cost(self) -> int: ...
    @abstractmethod
    def desc(self) -> str: ...

class Plain(Pizza):
    def cost(self): return 100
    def desc(self): return "plain"

class Topping(Pizza):
    def __init__(self, inner: Pizza):
        self._inner = inner
    def cost(self):
        return self._inner.cost()
    def desc(self):
        return self._inner.desc()

class Cheese(Topping):
    def cost(self): return self._inner.cost() + 30
    def desc(self): return self._inner.desc() + "+cheese"

class Capsicum(Topping):
    def cost(self): return self._inner.cost() + 20
    def desc(self): return self._inner.desc() + "+capsicum"

# order does not matter for pure addition, but does for transforms
order = Capsicum(Cheese(Plain()))
print(order.desc(), order.cost())  # plain+cheese+capsicum 150
